import React, { useState } from 'react';

const WHATSAPP_NUMBER = "201000000000";

const products = [
  { id: 1, name: "هودي بروكلين", category: "جاكيتات", icon: "🧥", price: 480, oldPrice: 600, discount: 20, rating: 4.8, store: "محل كفر الشيخ", material: "قطن 100%", sizes: ["M", "L", "XL"], colors: ["أسود", "رمادي"], desc: "هودي شتوي بخامة قطن ثقيلة وطبعة بروكلين أمامية." },
    { id: 2, name: "تيشيرت كينج", category: "تيشيرتات", icon: "👕", price: 255, oldPrice: 300, discount: 15, rating: 4.7, store: "محل كفر الشيخ", material: "قطن بيما", sizes: ["S", "M", "L"], colors: ["أبيض", "أسود"], desc: "تيشيرت قطن مريح بطبعة تاج صغيرة." },
      { id: 3, name: "بنطلون جينز", category: "بنطلونات", icon: "👖", price: 450, oldPrice: 500, discount: 10, rating: 4.5, store: "محل كفر الشيخ", material: "جينز", sizes: ["30", "32", "34", "36"], colors: ["أزرق", "أسود"], desc: "بنطلون جينز قصة مستقيمة بخامة متينة." },
        { id: 4, name: "قميص كلاسيك", category: "قمصان", icon: "👔", price: 300, oldPrice: 350, discount: 14, rating: 4.6, store: "محل كفر الشيخ", material: "قطن مخلوط", sizes: ["M", "L", "XL"], colors: ["أبيض", "سماوي"], desc: "قميص كلاسيك مناسب للشغل والمناسبات." }
        ];

        const categories = [
          { icon: "🏷️", name: "عروض" },
            { icon: "👕", name: "تيشيرتات" },
              { icon: "👖", name: "بنطلونات" },
                { icon: "🧥", name: "جاكيتات" },
                  { icon: "👔", name: "قمصان" },
                    { icon: "🔲", name: "كل الأقسام" }
                    ];

                    const tabs = [
                      { id: "home", icon: "🏠", name: "الرئيسية" },
                        { id: "stores", icon: "🏪", name: "متاجري" },
                          { id: "sections", icon: "🔲", name: "الأقسام" },
                            { id: "orders", icon: "📋", name: "طلباتي" },
                              { id: "account", icon: "👤", name: "حسابي" }
                              ];

                              function App() {
                                const [query, setQuery] = useState("");
                                  const [tab, setTab] = useState("home");
                                    const [selectedId, setSelectedId] = useState<number | null>(null);
                                      const [category, setCategory] = useState("كل الأقسام");
                                        const [minPrice, setMinPrice] = useState("");
                                          const [maxPrice, setMaxPrice] = useState("");
                                            const [sort, setSort] = useState("none");

                                              let results = products.filter((product) => {
                                                  const matchName = product.name.includes(query.trim());
                                                      const matchCategory =
                                                            category === "كل الأقسام" ||
                                                                  (category === "عروض" ? product.discount > 0 : product.category === category);
                                                                      const matchMin = minPrice === "" || product.price >= Number(minPrice);
                                                                          const matchMax = maxPrice === "" || product.price <= Number(maxPrice);
                                                                              return matchName && matchCategory && matchMin && matchMax;
                                                                                });

                                                                                  if (sort === "asc") {
                                                                                      results = [...results].sort((a, b) => a.price - b.price);
                                                                                        } else if (sort === "desc") {
                                                                                            results = [...results].sort((a, b) => b.price - a.price);
                                                                                              }

                                                                                                function nextSort() {
                                                                                                    if (sort === "none") setSort("asc");
                                                                                                        else if (sort === "asc") setSort("desc");
                                                                                                            else setSort("none");
                                                                                                              }

                                                                                                                const sortLabel =
                                                                                                                    sort === "asc" ? "⬆ الأرخص" : sort === "desc" ? "⬇ الأغلى" : "↕ ترتيب";

                                                                                                                      const currentTab = tabs.find((t) => t.id === tab);
                                                                                                                        const selected = products.find((p) => p.id === selectedId);

                                                                                                                          const whatsappLink = selected
                                                                                                                              ? "https://wa.me/" + WHATSAPP_NUMBER + "?text=" +
                                                                                                                                    encodeURIComponent("مرحباً، أريد طلب: " + selected.name + " - السعر: " + selected.price + " جنيه")
                                                                                                                                        : "#";

                                                                                                                                          return (
                                                                                                                                              <div className="app">
                                                                                                                                                    <div className="header">
                                                                                                                                                            <div className="bell">
                                                                                                                                                                      🔔<span className="badge">2</span>
                                                                                                                                                                              </div>
                                                                                                                                                                                      <div className="logo">
                                                                                                                                                                                                <h1>STYLE<span>K</span></h1>
                                                                                                                                                                                                          <p>ستايلك .. اختياراتك الأفضل</p>
                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                          <div className="city">📍 كفر الشيخ</div>
                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                      {selected ? (
                                                                                                                                                                                                                                              <div className="detail">
                                                                                                                                                                                                                                                        <button className="back" onClick={() => setSelectedId(null)}>→ رجوع</button>
                                                                                                                                                                                                                                                                  <div className="detail-img">{selected.icon}</div>
                                                                                                                                                                                                                                                                            <h2>{selected.name}</h2>
                                                                                                                                                                                                                                                                                      <p className="price">
                                                                                                                                                                                                                                                                                                  <span>{selected.price} EGP</span>
                                                                                                                                                                                                                                                                                                              <span className="old">{selected.oldPrice} EGP</span>
                                                                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                                                                                  <p className="store">🏪 {selected.store} | ⭐ {selected.rating}</p>

                                                                                                                                                                                                                                                                                                                                            <h4>المقاسات</h4>
                                                                                                                                                                                                                                                                                                                                                      <div className="chips">
                                                                                                                                                                                                                                                                                                                                                                  {selected.sizes.map((s) => (
                                                                                                                                                                                                                                                                                                                                                                                <span className="chip" key={s}>{s}</span>
                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                <h4>الألوان</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="chips">
                                                                                                                                                                                                                                                                                                                                                                                                                                      {selected.colors.map((c) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="chip" key={c}>{c}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h4>الخامة</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="desc">{selected.material}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h4>الوصف</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="desc">{selected.desc}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <a className="whatsapp" href={whatsappLink} target="_blank" rel="noreferrer">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        اطلب عبر واتساب
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) : tab === "home" ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="search"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      placeholder="ابحث عن ملابس أو متجر..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={query}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={(e) => setQuery(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="banner">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h2>ستايلك <span>دايماً أجمل</span></h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>أزياء عصرية .. بأسعار مميزة</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button>تسوق الآن</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="cats">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {categories.map((c) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className={c.name === category ? "cat active" : "cat"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    key={c.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => setCategory(c.name)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>{c.icon}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {c.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="filters">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="من سعر"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={minPrice}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) => setMinPrice(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="إلى سعر"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={maxPrice}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) => setMaxPrice(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onClick={nextSort}>{sortLabel}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="section-title">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h3>{category === "كل الأقسام" ? "أحدث المنتجات" : category}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span>{results.length} منتج</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="cards">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {results.map((product) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="card" key={product.id} onClick={() => setSelectedId(product.id)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="img">{product.icon}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="heart">🤍</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="discount">{product.discount}% -</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="info">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h2>{product.name}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="price">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <span>{product.price} EGP</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="old">{product.oldPrice} EGP</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="meta">⭐ {product.rating} | متوفر</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button>🛒 أضف للسلة</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {results.length === 0 && <p className="empty">لا توجد نتائج</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="page">{currentTab?.icon} {currentTab?.name}<br />قريباً</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="nav">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {tabs.map((t) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      key={t.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  className={t.id === tab && !selected ? "nav-item active" : "nav-item"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onClick={() => { setSelectedId(null); setTab(t.id); }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>{t.icon}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {t.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export default App;